// Generated by scripts/embed-views.mjs. Do not edit by hand.
export const generatedViews: Record<string, string> = {"404.ejs":"<%- include('partials/header') %>\n\n<section class=\"thanks shell\">\n  <p class=\"eyebrow\">404 / NOT FOUND</p>\n  <h1>This page<br><em>isn’t here.</em></h1>\n  <a class=\"button\" href=\"/\">Return home</a>\n</section>\n\n<%- include('partials/footer') %>\n","about.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\">HADI DIGITAL CRAFT / GUJRAT</p>\n  <h1>Print, guided by<br><em>the real object.</em></h1>\n  <p class=\"lead\">HDC helps customers move from an idea to a production brief that accounts for artwork, material, dimensions, use and finish.</p>\n</section>\n\n<section class=\"section shell about-grid\">\n  <div>\n    <p class=\"eyebrow\">THE ORVIA WORKFLOW</p>\n    <h2>Clear inputs.<br>Thoughtful <em>review.</em></h2>\n  </div>\n  <div>\n    <p>ORVIA keeps catalogue language connected to approved production information. Customers can share what they know; HDC reviews the open questions before confirming a process or price.</p>\n    <p>The site keeps the product they want, the surface it will meet, the production route and the page configuration in separate records. This gives HDC a clearer path to qualify a job without treating a product name as a compatibility promise.</p>\n    <a class=\"text-link\" href=\"/faq\">Read common questions ↗</a>\n  </div>\n</section>\n\n<%- include('partials/footer') %>\n","admin.ejs":"<%- include('partials/header') %>\n\n<section class=\"admin-page shell\">\n  <div class=\"admin-top\">\n    <div>\n      <p class=\"eyebrow\">ORVIA · ADMIN</p>\n      <h1>Review desk</h1>\n    </div>\n    <div style=\"display: flex; gap: 16px; align-items: center;\">\n      <a class=\"button button-small\" href=\"/admin/export.csv\">Export quote CSV</a>\n      <form method=\"post\" action=\"/admin/logout\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n        <button class=\"quiet-button\" type=\"submit\">Sign out</button>\n      </form>\n    </div>\n  </div>\n\n  <h2>Quote requests <span class=\"count\"><%= quotes.length %></span></h2>\n  <% if (!quotes || quotes.length === 0) { %>\n    <p>No requests yet.</p>\n  <% } else { %>\n    <div class=\"table-wrap\">\n      <table>\n        <thead>\n          <tr>\n            <th>Received</th>\n            <th>Customer</th>\n            <th>Service</th>\n            <th>Brief &amp; artwork</th>\n            <th>Status</th>\n          </tr>\n        </thead>\n        <tbody>\n          <% quotes.forEach(q => { %>\n            <tr>\n              <td><%= q.created_at %></td>\n              <td>\n                <%= q.customer_name %><br>\n                <a href=\"mailto:<%= q.email %>\"><%= q.email %></a>\n                <% if (q.phone) { %><br><small><%= q.phone %></small><% } %>\n              </td>\n              <td>\n                <%= q.product_name || 'To be confirmed' %>\n                <% if (q.matched_price_pkr) { %>\n                  <br><strong>Exact matrix: PKR <%= q.matched_price_pkr %></strong>\n                <% } %>\n                <% \n                  let evaluation = null;\n                  try { evaluation = q.evaluation_json ? JSON.parse(q.evaluation_json) : null; } catch(e){}\n                  if (evaluation && evaluation.base_sheet_price) { \n                %>\n                  <br><small>A3 base: PKR 2,500 / sheet · total not calculated</small>\n                <% } %>\n              </td>\n              <td>\n                <p style=\"margin: 0 0 6px;\"><%= q.details %></p>\n                <% const files = artworkByQuote[q.id] || []; %>\n                <% files.forEach(file => { %>\n                  <div><a href=\"/admin/artwork?id=<%= file.id %>\">📎 Download <%= file.original_name %></a></div>\n                <% }); %>\n              </td>\n              <td>\n                <form method=\"post\" action=\"/admin/quote\" style=\"display: inline-flex; gap: 6px; align-items: center; margin-bottom: 8px;\">\n                  <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n                  <input type=\"hidden\" name=\"id\" value=\"<%= q.id %>\">\n                  <select name=\"status\">\n                    <option value=\"new\" <%= q.status === 'new' ? 'selected' : '' %>>New</option>\n                    <option value=\"in_review\" <%= q.status === 'in_review' ? 'selected' : '' %>>In review</option>\n                    <option value=\"awaiting_customer\" <%= q.status === 'awaiting_customer' ? 'selected' : '' %>>Awaiting customer</option>\n                    <option value=\"quoted\" <%= q.status === 'quoted' ? 'selected' : '' %>>Quoted</option>\n                    <option value=\"closed\" <%= q.status === 'closed' ? 'selected' : '' %>>Closed</option>\n                  </select>\n                  <button class=\"quiet-button\" type=\"submit\">Save</button>\n                </form>\n                <% if (q.status === 'quoted') { %>\n                  <form method=\"post\" action=\"/admin/job\">\n                    <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n                    <input type=\"hidden\" name=\"quote_id\" value=\"<%= q.id %>\">\n                    <button class=\"button button-small\" type=\"submit\">Create job record</button>\n                  </form>\n                <% } %>\n              </td>\n            </tr>\n          <% }); %>\n        </tbody>\n      </table>\n    </div>\n  <% } %>\n\n  <h2>Job records</h2>\n  <% if (!jobs || jobs.length === 0) { %>\n    <p>No quote has been converted into a job record.</p>\n  <% } else { %>\n    <div class=\"table-wrap\">\n      <table>\n        <thead>\n          <tr>\n            <th>Reference</th>\n            <th>Quote</th>\n            <th>Created</th>\n            <th>Job status</th>\n            <th>Update</th>\n          </tr>\n        </thead>\n        <tbody>\n          <% jobs.forEach(job => { %>\n            <tr>\n              <td><strong><%= job.job_reference %></strong></td>\n              <td>#<%= job.quote_id %></td>\n              <td><%= job.created_at %></td>\n              <td><span class=\"status status-<%= job.status %>\"><%= job.status.replace(/_/g, ' ') %></span></td>\n              <td>\n                <form method=\"post\" action=\"/admin/job/status\" style=\"display: inline-flex; gap: 6px; align-items: center;\">\n                  <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n                  <input type=\"hidden\" name=\"id\" value=\"<%= job.id %>\">\n                  <select name=\"status\">\n                    <% ['awaiting_customer_approval','approved','in_production','quality_check','ready','completed','on_hold','cancelled'].forEach(opt => { %>\n                      <option value=\"<%= opt %>\" <%= job.status === opt ? 'selected' : '' %>><%= opt.replace(/_/g, ' ') %></option>\n                    <% }); %>\n                  </select>\n                  <button class=\"quiet-button\" type=\"submit\">Save</button>\n                </form>\n              </td>\n            </tr>\n          <% }); %>\n        </tbody>\n      </table>\n    </div>\n  <% } %>\n\n  <h2>Catalogue review</h2>\n  <p class=\"small-note\">Entries start as drafts. Confirm copy, configuration, process route and price matrix with production before publishing.</p>\n  <div class=\"admin-products\">\n    <% products.forEach(p => { %>\n      <details class=\"admin-product\">\n        <summary>\n          <span><%= p.name %></span>\n          <span class=\"status status-<%= p.status %>\"><%= p.status %></span>\n        </summary>\n        <form method=\"post\" action=\"/admin/product\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n          <input type=\"hidden\" name=\"id\" value=\"<%= p.id %>\">\n          <label>Short description\n            <input name=\"short_description\" value=\"<%= p.short_description %>\">\n          </label>\n          <label>Detailed description\n            <textarea name=\"description\" rows=\"5\"><%= p.description %></textarea>\n          </label>\n          <label style=\"display: flex; align-items: center; gap: 8px;\">\n            <input type=\"checkbox\" name=\"production_approved\" value=\"1\" <%= p.production_approved ? 'checked' : '' %>>\n            Production approval\n          </label>\n          <label style=\"display: flex; align-items: center; gap: 8px;\">\n            <input type=\"checkbox\" name=\"public_visibility\" value=\"1\" <%= p.public_visibility ? 'checked' : '' %>>\n            Public listing approval\n          </label>\n          <label>Approval note\n            <input name=\"approval_note\" maxlength=\"1000\" value=\"<%= p.approval_note || '' %>\" placeholder=\"Production profile / owner approval reference\">\n          </label>\n          <label>Approved configuration profile\n            <textarea name=\"profile_json\" rows=\"5\" required><%= p.profile_json || '{\"approved_fields\":[],\"compatibility_rules\":[],\"notes\":\"\"}' %></textarea>\n          </label>\n          <p class=\"small-note\">Valid JSON only. Include the approved options, surface compatibility and process rules. Publication requires an approved profile.</p>\n          <label>Publication\n            <select name=\"status\">\n              <option value=\"draft\" <%= p.status === 'draft' ? 'selected' : '' %>>Draft</option>\n              <option value=\"published\" <%= p.status === 'published' ? 'selected' : '' %>>Publish after production approval</option>\n            </select>\n          </label>\n          <button class=\"button button-small\" type=\"submit\">Save review</button>\n        </form>\n      </details>\n    <% }); %>\n  </div>\n\n  <h2>Exact price matrix</h2>\n  <p class=\"small-note\">Add only owner-approved price rows. Configuration JSON must match the submitted configuration exactly. No calculated fallback is used.</p>\n  <form class=\"price-form\" method=\"post\" action=\"/admin/price\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n    <label>Approved product\n      <select name=\"product_id\" required>\n        <option value=\"\">Choose a production-approved product</option>\n        <% products.forEach(p => { %>\n          <% if (p.status === 'published' && p.production_approved && p.public_visibility) { %>\n            <option value=\"<%= p.id %>\"><%= p.name %></option>\n          <% } %>\n        <% }); %>\n      </select>\n    </label>\n    <label>Exact configuration JSON\n      <textarea name=\"configuration_json\" rows=\"4\" required placeholder='{\"quantity\":500,\"print_colors\":1}'></textarea>\n    </label>\n    <label>Approved amount (PKR)\n      <input type=\"number\" name=\"price_pkr\" min=\"0.01\" step=\"0.01\" required>\n    </label>\n    <button class=\"button button-small\" type=\"submit\">Save exact price row</button>\n  </form>\n</section>\n\n<%- include('partials/footer') %>\n","catalogue.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\"><span class=\"index\">01</span> PRINT SERVICE INDEX</p>\n  <h1>Find your<br><em>starting point.</em></h1>\n  <p class=\"lead\">Explore HDC’s approved print services. Each project is reviewed against its own artwork, material and use.</p>\n</section>\n\n<section class=\"section shell\">\n  <% if (products && products.length) { %>\n    <div class=\"product-grid\">\n      <% products.forEach(p => { %>\n        <%- include('partials/product_card', { p }) %>\n      <% }); %>\n    </div>\n  <% } else { %>\n    <div class=\"empty-state\">\n      <h2>Catalogue entries are being reviewed.</h2>\n      <p>Product listings publish only after HDC confirms the production options and service details.</p>\n      <a class=\"button\" href=\"/quote\">Request a project review</a>\n    </div>\n  <% } %>\n</section>\n\n<%- include('partials/footer') %>\n","faq.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\">BEFORE YOU SEND A BRIEF</p>\n  <h1>Useful <em>answers.</em></h1>\n  <p class=\"lead\">The production team confirms options against the actual artwork and application.</p>\n</section>\n\n<section class=\"section shell faq-list\">\n  <% siteContent.faqs.forEach(item => { %>\n    <details class=\"faq-item\">\n      <summary><%= item[0] %></summary>\n      <p><%= item[1] %></p>\n    </details>\n  <% }); %>\n</section>\n\n<%- include('partials/footer') %>\n","finishing.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\">SERVICE 05 / FINISHING &amp; EMBELLISHMENT</p>\n  <h1>The final surface<br>is part of the <em>design.</em></h1>\n  <p class=\"lead\">Protection, reflection, dimension and final form—selected only after the material, artwork, construction and intended use are understood.</p>\n  <div class=\"finish-taxonomy\">\n    <% siteContent.finishes.forEach(finish => { %>\n      <span><%= finish.label %></span>\n    <% }); %>\n  </div>\n</section>\n\n<section class=\"section shell finishing-grid\">\n  <div>\n    <p class=\"eyebrow\">A FINISH SHOULD EARN ITS PLACE</p>\n    <h2>Make the object<br>work <em>harder.</em></h2>\n    <p class=\"section-lead\">Finishing changes how a piece is handled, read, assembled and experienced. Availability and method remain job-specific.</p>\n    <a class=\"button\" href=\"/quote\">Discuss a finishing brief ↗</a>\n  </div>\n  <div class=\"finish-list\" role=\"group\" aria-label=\"Finishing intents\">\n    <% siteContent.finishes.forEach((finish, i) => { %>\n      <details class=\"finish-item\" <%= i === 0 ? 'open' : '' %>>\n        <summary>\n          <span class=\"eyebrow\">0<%= i + 1 %> / <%= finish.label %></span>\n          <strong><%= finish.title %></strong>\n        </summary>\n        <p><%= finish.description %></p>\n      </details>\n    <% }); %>\n  </div>\n</section>\n\n<%- include('partials/footer') %>\n","home.ejs":"<%- include('partials/header') %>\n\n<section class=\"hero shell\">\n  <div class=\"hero-copy\">\n    <p class=\"eyebrow\"><span class=\"index\">01</span> PRINTING, CONSIDERED</p>\n    <h1>Make the thing<br>they <em>remember.</em></h1>\n    <p class=\"lead\">A considered print partner for objects, packaging and campaigns. Start with the idea; we’ll help shape the production brief.</p>\n    <div class=\"hero-actions\">\n      <a class=\"button\" href=\"/quote\">Tell us about your project <span aria-hidden=\"true\">↗</span></a>\n      <a class=\"quiet-link\" href=\"/products\">Explore print services</a>\n    </div>\n    <div class=\"hero-note\">\n      <span class=\"rule\"></span>\n      <span>Artwork first. Production details confirmed with care.</span>\n    </div>\n  </div>\n  <div class=\"hero-visual\" aria-label=\"Image slot reserved for an approved HDC print-work photograph\">\n    <div class=\"visual-label\">IMAGE SLOT · HERO / 4:5</div>\n    <div class=\"visual-lines\"></div>\n    <div class=\"visual-caption\">\n      <span>01 / MATERIAL STUDY</span>\n      <span>HDC · GUJRAT</span>\n    </div>\n  </div>\n  <div class=\"hero-index\">HDC / 01 — 04</div>\n</section>\n\n<section class=\"intro-band\">\n  <div class=\"shell band-grid\">\n    <p class=\"eyebrow\">A BETTER BRIEF MAKES A BETTER PRINT</p>\n    <p>UV printing and UV DTF are among the processes HDC uses across many products. The right route depends on the actual product, artwork, surface and production profile.</p>\n    <a href=\"/quote\" class=\"text-link\">Bring us the details ↗</a>\n  </div>\n</section>\n\n<section class=\"section shell service-territories\" id=\"services\">\n  <div class=\"section-heading\">\n    <div>\n      <p class=\"eyebrow\"><span class=\"index\">02</span> THE SERVICE INDEX</p>\n      <h2>Print for the<br><em>next good idea.</em></h2>\n    </div>\n    <p class=\"section-lead\">Every project has its own material, scale and purpose. Choose a service territory or send HDC a brief to begin a review.</p>\n  </div>\n  <div class=\"territory-grid\">\n    <% Object.keys(siteContent.services).forEach((slug, idx) => { \n       const group = siteContent.services[slug]; %>\n      <a class=\"territory-card\" href=\"/services/<%= slug %>\">\n        <span class=\"eyebrow\">SERVICE / 0<%= idx + 1 %></span>\n        <h3><%= group.title %></h3>\n        <p><%= group.lead %></p>\n        <span class=\"text-link\">Explore territory ↗</span>\n      </a>\n    <% }); %>\n  </div>\n\n  <% if (products && products.length) { %>\n    <div class=\"section-heading approved-heading\">\n      <div>\n        <p class=\"eyebrow\">CURRENT APPROVED CATALOGUE</p>\n        <h2>Product<br><em>index.</em></h2>\n      </div>\n      <a class=\"quiet-link\" href=\"/products\">Browse every approved product</a>\n    </div>\n    <div class=\"product-grid\">\n      <% products.forEach(p => { %>\n        <%- include('partials/product_card', { p }) %>\n      <% }); %>\n    </div>\n  <% } else { %>\n    <div class=\"empty-state\">\n      <span class=\"eyebrow\">CATALOGUE IN REVIEW</span>\n      <h3>Product options are being verified.</h3>\n      <p>Ask about your project while HDC confirms production details and publishes approved catalogue entries.</p>\n      <a class=\"text-link\" href=\"/quote\">Request a review ↗</a>\n    </div>\n  <% } %>\n</section>\n\n<section class=\"process-section\" id=\"process\">\n  <div class=\"shell process-grid\">\n    <div>\n      <p class=\"eyebrow\"><span class=\"index\">03</span> THE ORVIA METHOD</p>\n      <h2>Good work starts<br>with <em>good questions.</em></h2>\n    </div>\n    <ol class=\"steps\">\n      <li>\n        <span>01</span>\n        <div>\n          <h3>Share the intent</h3>\n          <p>Tell us what you’re making, where it will be used and what you already know.</p>\n        </div>\n      </li>\n      <li>\n        <span>02</span>\n        <div>\n          <h3>Review the details</h3>\n          <p>We check the artwork, material, dimensions and any process information that needs confirmation.</p>\n        </div>\n      </li>\n      <li>\n        <span>03</span>\n        <div>\n          <h3>Confirm the brief</h3>\n          <p>HDC follows up with production questions and a quote based on approved specifications.</p>\n        </div>\n      </li>\n    </ol>\n  </div>\n</section>\n\n<section class=\"closing shell\">\n  <p class=\"eyebrow\">READY WHEN YOU ARE</p>\n  <h2>Let’s get the<br><em>specification right.</em></h2>\n  <a class=\"button\" href=\"/quote\">Start a project <span aria-hidden=\"true\">↗</span></a>\n</section>\n\n<%- include('partials/footer') %>\n","login.ejs":"<%- include('partials/header') %>\n\n<section class=\"admin-login\">\n  <p class=\"eyebrow\">HDC · ORVIA ADMIN</p>\n  <h1>Review desk</h1>\n  <form method=\"post\" action=\"/admin/login\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n    <label>Email\n      <input type=\"email\" name=\"email\" required autocomplete=\"username\" placeholder=\"admin@hdc.com\">\n    </label>\n    <label>Password\n      <input type=\"password\" name=\"password\" required autocomplete=\"current-password\">\n    </label>\n    <button class=\"button\" type=\"submit\">Sign in</button>\n  </form>\n</section>\n\n<%- include('partials/footer') %>\n","partials/footer.ejs":"  </main>\n  <% if (!path.startsWith('/admin')) { %>\n    <footer class=\"site-footer\">\n      <div class=\"shell footer-main\">\n        <a class=\"brand\" href=\"/\">\n          <span class=\"brand-mark\">H</span>\n          <span>HADI DIGITAL CRAFT<small>PRINT · FINISH · FORM</small></span>\n        </a>\n        <p>Thoughtful print production,<br>reviewed around your brief.</p>\n        <nav class=\"footer-links\">\n          <a href=\"/services\">Services</a>\n          <a href=\"/finishing\">Finishing</a>\n          <a href=\"/surface-lab\">Surface Lab</a>\n          <a href=\"/about\">About</a>\n          <a href=\"/faq\">FAQ</a>\n          <a href=\"/quote\">Start a project ↗</a>\n        </nav>\n      </div>\n      <div class=\"shell footer-bottom\">\n        <span>© <%= new Date().getFullYear() %> Hadi Digital Craft</span>\n        <span>Powered by ORVIA · Review before release</span>\n      </div>\n    </footer>\n  <% } %>\n  <script src=\"/assets/site.js\" defer></script>\n</body>\n</html>\n","partials/header.ejs":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#0B1013\">\n  <meta name=\"description\" content=\"Thoughtful print production, reviewed around your artwork, material and intended use.\">\n  <title><%= title %></title>\n  <link rel=\"stylesheet\" href=\"/assets/site.css\">\n</head>\n<body>\n  <a class=\"skip-link\" href=\"#main-content\">Skip to content</a>\n  <% if (!path.startsWith('/admin')) { %>\n    <header class=\"site-header\">\n      <a class=\"brand\" href=\"/\" aria-label=\"Hadi Digital Craft home\">\n        <span class=\"brand-mark\">H</span>\n        <span>HADI DIGITAL CRAFT<small>PRINT · FINISH · FORM</small></span>\n      </a>\n      <button class=\"nav-toggle\" aria-expanded=\"false\" aria-controls=\"main-nav\">Menu</button>\n      <nav id=\"main-nav\">\n        <a href=\"/services\">Services</a>\n        <a href=\"/finishing\">Finishing</a>\n        <a href=\"/surface-lab\">Surface Lab</a>\n        <a href=\"/#process\">How we work</a>\n        <a class=\"button button-small\" href=\"/quote\">Start a project <span aria-hidden=\"true\">↗</span></a>\n      </nav>\n    </header>\n  <% } %>\n\n  <% if (notice) { %>\n    <div class=\"notice\" role=\"status\"><%= notice %></div>\n  <% } %>\n  <% if (error) { %>\n    <div class=\"notice notice-error\" role=\"alert\"><%= error %></div>\n  <% } %>\n\n  <main id=\"main-content\">\n","partials/product_card.ejs":"<a class=\"product-card\" href=\"/products/<%= p.slug %>\">\n  <span class=\"eyebrow\"><%= p.family %></span>\n  <h3><%= p.name %></h3>\n  <p><%= p.short_description %></p>\n  <span class=\"text-link\">Explore service <span aria-hidden=\"true\">↗</span></span>\n</a>\n","product.ejs":"<%- include('partials/header') %>\n\n<section class=\"product-detail shell\">\n  <div class=\"product-copy\">\n    <p class=\"eyebrow\"><a href=\"/products\">SERVICE INDEX</a> / <%= product.family %></p>\n    <h1><%= product.name %><em>.</em></h1>\n    <p class=\"lead\"><%= product.short_description %></p>\n    <div class=\"product-description\">\n      <%- product.description.replace(/\\n/g, '<br>') %>\n    </div>\n    <a class=\"button\" href=\"/quote?product=<%= product.slug %>\">Request a quote <span aria-hidden=\"true\">↗</span></a>\n  </div>\n  <aside class=\"product-aside\">\n    <div class=\"image-placeholder\">\n      <span class=\"eyebrow\">PRODUCT IMAGE SLOT</span>\n      <span><%= product.slug %> · 4:5</span>\n    </div>\n    <p class=\"eyebrow\">PROJECT DETAILS</p>\n    <p><%= product.configure || product.typical_uses || 'Custom specification reviewed by HDC' %></p>\n    <% if (product.template === 'B') { %>\n      <div class=\"review-note\">\n        <strong>SURFACE / APPLICATION REVIEW</strong>\n        <p>Share the object, surface, coating, geometry, printable area and intended use. HDC checks the specific combination before confirming a route.</p>\n      </div>\n    <% } %>\n    <p class=\"small-note\">Final options, process suitability and pricing are confirmed by HDC against the approved production profile.</p>\n  </aside>\n</section>\n\n<%- include('partials/footer') %>\n","quote.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\"><span class=\"index\">01</span> PROJECT INTAKE · ORVIA</p>\n  <h1>Tell us what<br>you’re <em>making.</em></h1>\n  <p class=\"lead\">Share the essentials. HDC will review the request and follow up to confirm the production brief and pricing.</p>\n</section>\n\n<section class=\"quote-wrap shell\">\n  <form method=\"post\" action=\"/quote\" class=\"quote-form\" enctype=\"multipart/form-data\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"<%= csrfToken %>\">\n    <label class=\"hp-field\" aria-hidden=\"true\">Website\n      <input name=\"website_url\" tabindex=\"-1\" autocomplete=\"off\">\n    </label>\n    <label>Your name\n      <input name=\"name\" required maxlength=\"120\" autocomplete=\"name\">\n    </label>\n    <div class=\"form-row\">\n      <label>Email\n        <input type=\"email\" name=\"email\" required maxlength=\"190\" autocomplete=\"email\">\n      </label>\n      <label>Phone / WhatsApp <span class=\"optional\">optional</span>\n        <input name=\"phone\" maxlength=\"60\" autocomplete=\"tel\">\n      </label>\n    </div>\n    <label>Service <span class=\"optional\">optional</span>\n      <select name=\"product_id\">\n        <option value=\"\">I’m not sure yet</option>\n        <% products.forEach(p => { %>\n          <option value=\"<%= p.id %>\" data-slug=\"<%= p.slug %>\" data-template=\"<%= p.template %>\" <%= (quoteProduct && quoteProduct.id == p.id) ? 'selected' : '' %>>\n            <%= p.name %>\n          </option>\n        <% }); %>\n      </select>\n    </label>\n    <label>Artwork files <span class=\"optional\">optional · PDF, PNG, JPEG, TIFF, EPS · up to 5 files / 25 MB each</span>\n      <input type=\"file\" name=\"artwork\" accept=\".pdf,.png,.jpg,.jpeg,.tif,.tiff,.eps,application/pdf,image/png,image/jpeg,image/tiff,application/postscript\" multiple>\n    </label>\n    <label>Project details\n      <textarea name=\"details\" required minlength=\"12\" maxlength=\"6000\" rows=\"6\" placeholder=\"What are you printing? Include size, quantity, material or intended use if known.\"></textarea>\n    </label>\n    <div class=\"commercial-fields\" hidden>\n      <label>Quantity\n        <input name=\"configuration[quantity]\" type=\"number\" min=\"1\" inputmode=\"numeric\">\n      </label>\n      <label class=\"size-field\" hidden>Finished size\n        <input name=\"configuration[finished_size]\" maxlength=\"80\" placeholder=\"For example, A3\">\n      </label>\n      <label class=\"color-field\" hidden>Print colors\n        <select name=\"configuration[print_colors]\">\n          <option value=\"\">Select</option>\n          <option>1</option>\n          <option>2</option>\n          <option>4</option>\n        </select>\n      </label>\n      <label class=\"sheet-field\" hidden>Sheet size\n        <select name=\"configuration[sheet_size]\">\n          <option value=\"\">Select</option>\n          <option>A3</option>\n          <option>Other / please specify</option>\n        </select>\n      </label>\n      <fieldset class=\"surface-fields\" hidden>\n        <legend>Surface / application details</legend>\n        <label>Material or surface\n          <input name=\"configuration[surface]\" maxlength=\"160\">\n        </label>\n        <label>Object geometry\n          <input name=\"configuration[geometry]\" maxlength=\"160\">\n        </label>\n        <label>Printable area\n          <input name=\"configuration[printable_area]\" maxlength=\"120\">\n        </label>\n        <label>Intended use\n          <input name=\"configuration[intended_use]\" maxlength=\"300\">\n        </label>\n      </fieldset>\n      <p class=\"small-note commercial-note\"></p>\n    </div>\n    <p class=\"small-note\">Artwork stays in private server storage. Only signed-in admins can download it. Avoid sending confidential personal information.</p>\n    <button class=\"button\" type=\"submit\">Send project brief <span aria-hidden=\"true\">↗</span></button>\n  </form>\n  <aside class=\"quote-aside\">\n    <p class=\"eyebrow\">WHAT HAPPENS NEXT</p>\n    <h2>Review before<br>recommendation.</h2>\n    <ol>\n      <li>We check the request and any production questions.</li>\n      <li>We confirm options and pricing from approved specifications.</li>\n      <li>You receive a clear next step before production begins.</li>\n    </ol>\n  </aside>\n</section>\n\n<%- include('partials/footer') %>\n","service.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\"><%= service.kicker %></p>\n  <h1><%= service.title %><em>.</em></h1>\n  <p class=\"lead\"><%= service.lead %></p>\n</section>\n\n<section class=\"section shell service-detail\">\n  <div class=\"service-manifesto\">\n    <p class=\"eyebrow\">START WITH THE JOB</p>\n    <p><%= service.body %></p>\n    <a class=\"button\" href=\"/quote\">Describe your project <span aria-hidden=\"true\">↗</span></a>\n    <a class=\"quiet-link\" href=\"/surface-lab\">Open the Surface Lab</a>\n  </div>\n  <div>\n    <p class=\"eyebrow\">RELATED PRODUCT RECORDS</p>\n    <% if (related && related.length) { %>\n      <div class=\"product-grid service-products\">\n        <% related.forEach(p => { %>\n          <%- include('partials/product_card', { p }) %>\n        <% }); %>\n      </div>\n    <% } else { %>\n      <div class=\"empty-state\">\n        <h2>Production options are in review.</h2>\n        <p>Send HDC the application and material details for a project-specific response.</p>\n      </div>\n    <% } %>\n  </div>\n</section>\n\n<%- include('partials/footer') %>\n","services.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\">HDC / SERVICE TERRITORIES</p>\n  <h1>Four ways<br>to <em>begin.</em></h1>\n  <p class=\"lead\">Start with the outcome you need. Product options and production routes are confirmed against the real job.</p>\n</section>\n\n<section class=\"section shell\">\n  <div class=\"territory-grid\">\n    <% Object.keys(siteContent.services).forEach(slug => { \n       const group = siteContent.services[slug]; %>\n      <a class=\"territory-card\" href=\"/services/<%= slug %>\">\n        <span class=\"eyebrow\"><%= group.kicker %></span>\n        <h3><%= group.title %></h3>\n        <p><%= group.lead %></p>\n        <span class=\"text-link\">Explore territory ↗</span>\n      </a>\n    <% }); %>\n  </div>\n</section>\n\n<%- include('partials/footer') %>\n","surface-lab.ejs":"<%- include('partials/header') %>\n\n<section class=\"page-intro shell\">\n  <p class=\"eyebrow\">ORVIA / MATERIAL &amp; APPLICATION REVIEW</p>\n  <h1>Surface <em>Lab.</em></h1>\n  <p class=\"lead\">A material name is only a starting point. Compatibility follows the actual surface, geometry, coating, artwork and intended use.</p>\n</section>\n\n<section class=\"section shell\">\n  <div class=\"surface-intro\">\n    <p>HDC keeps product, material, production route and page configuration as separate records. A material listed here does not guarantee that every object made from it can be printed.</p>\n    <a class=\"button\" href=\"/quote\">Ask about a surface ↗</a>\n  </div>\n  <div class=\"surface-grid\">\n    <% siteContent.surfaces.forEach((surface, i) => { %>\n      <article class=\"surface-card\">\n        <span class=\"eyebrow\">SURFACE / 0<%= i + 1 %></span>\n        <h2><%= surface[0] %></h2>\n        <p><%= surface[1] %></p>\n        <a class=\"text-link\" href=\"/quote\">Request a compatibility review ↗</a>\n      </article>\n    <% }); %>\n  </div>\n  <div class=\"review-note\">\n    <p class=\"eyebrow\">PROCESS CANDIDATES</p>\n    <p>UV printing and UV DTF are distinct processes used across many products. Neither is assigned to a surface or product here without a product-specific approved production profile.</p>\n  </div>\n</section>\n\n<%- include('partials/footer') %>\n","thanks.ejs":"<%- include('partials/header') %>\n\n<section class=\"thanks shell\">\n  <p class=\"eyebrow\">PROJECT BRIEF RECEIVED</p>\n  <h1>Thank you.<br><em>We’ll review it.</em></h1>\n  <p class=\"lead\">HDC will check your request and get back to you about the next production step.</p>\n  <a class=\"button\" href=\"/\">Return home</a>\n</section>\n\n<%- include('partials/footer') %>\n"};
